pub fn area_a(w: i32, h: i32) -> i32 {
    let scaled = w * 2;
    scaled * h
}

pub fn area_b(w: i32, h: i32) -> i32 {
    let scaled = w * 2;
    scaled * h + 1
}

#[cfg(test)]
mod tests {
    #[test]
    fn unchanged() {
        assert_eq!(super::area_a(3, 4), 24);
        assert_eq!(super::area_b(3, 4), 25);
    }
}

